type ControllerV1 struct{}

func NewV1() *ControllerV1 {
	return &ControllerV1{}
}

func (c *ControllerV1) Tryon(ctx context.Context, req *v1.TryonReq) (res *v1.TryonRes, err error) {
	r := ghttp.RequestFromCtx(ctx)
	secService := security.GetService()
	imgLimits := imagevalidate.LoadImageLimits(ctx)

	// 1. 严格校验两张图片（人像和服装）真实格式、文件大小、尺寸及像素
	personImg, garmentImg, imgErr := imagevalidate.ValidateImagesPair(req.PersonImage, req.GarmentImage, imgLimits)
	if imgErr != nil {
		if apiErr, ok := imgErr.(*security.APIError); ok {
			middleware.WriteAPIError(r, apiErr)
			return nil, nil
		}
		middleware.WriteAPIError(r, security.ErrInvalidImageBase64)
		return nil, nil
	}

	// 1b. 姿势参考图（可选）：同样走严格校验
	var poseImg *imagevalidate.ValidatedImage
	if req.PoseImage != "" {
		p, poseErr := imagevalidate.ValidateImage(req.PoseImage, imgLimits)
		if poseErr != nil {
			if apiErr, ok := poseErr.(*security.APIError); ok {
				middleware.WriteAPIError(r, apiErr)
				return nil, nil
			}
			middleware.WriteAPIError(r, security.ErrInvalidImageBase64)
			return nil, nil
		}
		poseImg = p
	}

	// 2. 检查并原子扣减每日调用额度
	principalID := r.GetCtxVar(middleware.CtxPrincipalID).String()
	if principalID == "" {
		principalID = "anonymous"
	}
	if !secService.DailyQuotaTracker.CheckAndDeduct(principalID) {
		middleware.WriteAPIError(r, security.ErrDailyQuotaExceeded)
		return nil, nil
	}

	// 3. 并发控制（单 Token 并发与全局并发）
	release, ok := secService.ConcurrencyManager.Acquire(principalID)
	if !ok {
		middleware.WriteAPIError(r, security.ErrConcurrencyLimited)
		return nil, nil
	}
	defer release()

	var clientConfig *tryon.ModelConfig
	if req.ClientConfig != nil {
		clientConfig = &tryon.ModelConfig{
			Name:     "browser-custom",
			Provider: req.ClientConfig.Provider,
			APIKey:   req.ClientConfig.APIKey,
			BaseURL:  req.ClientConfig.BaseURL,
			Model:    req.ClientConfig.Model,
		}
	}

	imageB64, model, prompt, err := tryon.DoTryonWithOptions(
		ctx,
		personImg,
		garmentImg,
		poseImg,
		req.Model,
		req.Size,
		req.Lang,
		req.PersonNote,
		clientConfig,
	)
	if err != nil {
		if modErr, ok := tryon.AsModerationBlocked(err); ok {
			apiErr := security.NewModerationBlockedError(modErr.Kind == tryon.ModerationBlockedOutput, modErr.RequestID)
			g.Log().Warningf(ctx,
				"tryon moderation blocked code=%d error_code=%s kind=%s upstream_code=%s request_id=%s",
				apiErr.BizCode, apiErr.ErrorCode, modErr.Kind,
				logSafeToken(modErr.UpstreamCode), logSafeToken(modErr.RequestID),
			)
			middleware.WriteAPIError(r, apiErr)
			return nil, nil
		}
		return nil, err
	}
	imageMIME, err := tryon.DetectGeneratedImageMIME(imageB64)
	if err != nil {
		return nil, err
	}
	return &v1.TryonRes{
		Image:  imageB64,
		MIME:   imageMIME,
		Model:  model,
		Prompt: prompt,
	}, nil
}

func (c *ControllerV1) ComfyUIHealth(ctx context.Context, req *v1.ComfyUIHealthReq) (res *v1.ComfyUIHealthRes, err error) {
	model, healthErr := tryon.CheckComfyUI(ctx)
	if healthErr != nil {
		return &v1.ComfyUIHealthRes{
			Available: false,
			Message:   "本地 ComfyUI 或固定工作流不可用",
		}, nil
	}
	return &v1.ComfyUIHealthRes{
		Available: true,
		Model:     model,
		Message:   "本地 ComfyUI 固定工作流可用",
	}, nil
}

// TestConnection 设置中心的模型连通性诊断。handler 只做参数解析、配置读取、来源判断、计时与日志。
func (c *ControllerV1) TestConnection(ctx context.Context, req *v1.TestConnectionReq) (res *v1.TestConnectionRes, err error) {
	start := time.Now()
	r := ghttp.RequestFromCtx(ctx)
	mode := strings.ToLower(strings.TrimSpace(req.Mode))

	var result tryon.ProbeResult
	switch mode {
	case "server":
		result = serverConnectionProbe(ctx, req, r)
	case "personal":
		result = personalConnectionProbe(ctx, req)
	default:
		result = tryon.NewProbeConfigMissing("", "", "mode 必须为 server 或 personal", "请选择服务器预设或个人配置后重试")
	}

	result.ElapsedMs = time.Since(start).Milliseconds()
	g.Log().Infof(ctx,
		"test-connection mode=%s provider=%s probe=%s layer=%s status=%d elapsed_ms=%d upstream_requests=%d",
		logSafeToken(mode), logSafeToken(result.Provider), result.Probe, result.Layer,
		result.UpstreamStatus, result.ElapsedMs, result.UpstreamRequests,
	)

	return &v1.TestConnectionRes{
		OK:               result.OK,
		Layer:            result.Layer,
		Probe:            result.Probe,
		Provider:         result.Provider,
		Model:            result.Model,
		UpstreamStatus:   result.UpstreamStatus,
		ElapsedMs:        result.ElapsedMs,
		UpstreamRequests: result.UpstreamRequests,
		Message:          result.Message,
		Hint:             result.Hint,
		ErrorCode:        result.ErrorCode,
	}, nil
}

func serverConnectionProbe(ctx context.Context, req *v1.TestConnectionReq, r *ghttp.Request) tryon.ProbeResult {
	alias := strings.TrimSpace(req.Alias)
	if alias == "" {
		return tryon.NewProbeConfigMissing("", "", "模型别名未配置", "请在请求中指定 alias，或在设置页选择服务器预设模型")
	}
	cfg, cfgErr := tryon.LoadModelConfigForProbe(ctx, alias)
	if cfgErr != nil || cfg == nil {
		return tryon.NewProbeConfigMissing("", "", "模型别名未配置", "请在 config.yaml 的 llm.models 下配置该别名")
	}
	if tryon.CanonicalProbeProvider(cfg.Provider) == "comfyui" {
		return tryon.ProbeComfyUIConnection(ctx)
	}
	return tryon.TestConnection(ctx, tryon.ProbeOptions{
		Mode:            "server",
		Provider:        cfg.Provider,
		BaseURL:         cfg.BaseURL,
		APIKey:          cfg.APIKey,
		Model:           cfg.Model,
		EnvKey:          cfg.EnvKey,
		AllowGenerate:   isLoopbackClient(r),
		Timeout:         15 * time.Second,
		GenerateTimeout: 60 * time.Second,
	})
}

func personalConnectionProbe(ctx context.Context, req *v1.TestConnectionReq) tryon.ProbeResult {
	if strings.EqualFold(strings.TrimSpace(req.Provider), "comfyui") {
		return tryon.ProbeComfyUIConnection(ctx)
	}
	return tryon.TestConnection(ctx, tryon.ProbeOptions{
		Mode:             "personal",
		Provider:         req.Provider,
		BaseURL:          req.BaseURL,
		APIKey:           req.APIKey,
		Model:            req.Model,
		ClientRestricted: true,
		AllowGenerate:    true,
		Timeout:          15 * time.Second,
		GenerateTimeout:  60 * time.Second,
	})
}

// isLoopbackClient 以真实 TCP 对端地址为准判断是否本机来源。
// ghttp 的 GetClientIp 会信任 X-Forwarded-For，可被远程请求伪造，因此只在拿不到对端地址时兜底。
func isLoopbackClient(r *ghttp.Request) bool {
	if host, _, splitErr := net.SplitHostPort(strings.TrimSpace(r.RemoteAddr)); splitErr == nil {
		if ip := net.ParseIP(host); ip != nil {
			return ip.IsLoopback()
		}
	}
	ip := net.ParseIP(strings.TrimSpace(r.GetClientIp()))
	return ip != nil && ip.IsLoopback()
}

// logSafeToken 防止用户可控字段携带换行等字符污染结构化日志。
func logSafeToken(value string) string {
	return strings.Map(func(r rune) rune {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '_', r == '-', r == '.':
			return r
		default:
			return -1
		}
	}, value)
}
